Account Login - ArcGIS Survey123 




































 html,
 body {
   margin: 0;
 }

 #loading_bar {
   width: 34px;
   height: 34px;
   display: flex;
   justify-content: center;
   left: 50%;
   top: 50%;
   transform: translate(-50%, -50%);
   position: fixed;
 }

 #loading_bar .loading-bar {
   background-color: #31872E;
   width: 8px;
   margin: 0px;
   height: 34px;
   animation: survey123-loading-bar-index 0.7s ease-in-out infinite;
 }

 #loading_bar .loading-bar:nth-child(1) {
   animation-delay: 0s;
 }

 #loading_bar .loading-bar:nth-child(2) {
   animation-delay: 0.09s;
   margin-left: 5px;
   margin-right: 5px;
 }

 #loading_bar .loading-bar:nth-child(3) {
   animation-delay: 0.18s;
 }

 @keyframes survey123-loading-bar-index {

   100%,
   0% {
     height: 16px;
     margin-top: 18px;
   }

   50% {
     height: 34px;
     margin-top: 0px;
   }
 }
